package replicareplay

import "sync"

type record struct {
	request Request
	result  Result
}

// Backend stands in for state shared by independent service handles.
type Backend struct {
	mu      sync.Mutex
	records map[string]record
	entries []Result
	nextID  int64
}

func NewBackend() *Backend {
	return &Backend{records: make(map[string]record)}
}

type Store struct {
	backend *Backend
}

func NewStore(backend *Backend) *Store {
	return &Store{backend: backend}
}

func (s *Store) post(request Request) (Result, error) {
	s.backend.mu.Lock()
	defer s.backend.mu.Unlock()

	if stored, ok := s.backend.records[request.Key]; ok {
		if stored.request.Account != request.Account || stored.request.Amount != request.Amount {
			return Result{}, ErrKeyConflict
		}
		return stored.result, nil
	}

	s.backend.nextID++
	result := Result{EntryID: s.backend.nextID, Account: request.Account, Amount: request.Amount}
	s.backend.entries = append(s.backend.entries, result)
	s.backend.records[request.Key] = record{request: request, result: result}
	return result, nil
}

func (s *Store) Entries() []Result {
	s.backend.mu.Lock()
	defer s.backend.mu.Unlock()
	return append([]Result(nil), s.backend.entries...)
}

